<?php /** Contact-only footer: existing menus, real categories, provider newsletter. */ ?>
<footer class="fc-footer">
    <svg class="fc-footer-wave" viewBox="0 0 1440 42" preserveAspectRatio="none" aria-hidden="true" focusable="false"><path fill="currentColor" d="M0 28C165 -18 222 10 310 23S481 21 621 29 866 36 1023 24 1264 -11 1440 29V42H0Z"/></svg>
    <div class="fc-wrap fc-footer-grid">
        <div class="fc-footer-brand">
            <a class="fc-footer-logo" href="<?php echo esc_url( home_url( '/' ) ); ?>"><i class="fas fa-leaf" aria-hidden="true"></i><?php echo esc_html( get_bloginfo( 'name' ) ?: 'Fruitables' ); ?></a>
            <?php if ( $footer_tagline ) : ?><p><?php echo esc_html( $footer_tagline ); ?></p><?php endif; ?>
            <?php if ( $footer_about ) : ?><p><?php echo nl2br( esc_html( $footer_about ) ); ?></p><?php else : ?><p><?php esc_html_e( 'Your online store for fresh fruits and vegetables.', 'fruitables' ); ?></p><?php endif; ?>
            <?php if ( $footer_more ) : ?><a class="fc-footer-more" href="<?php echo esc_url( $footer_more ); ?>"><?php esc_html_e( 'Read More', 'fruitables' ); ?></a><?php endif; ?>
