        </div>
        <div><h2><?php esc_html_e( 'Shop', 'fruitables' ); ?></h2><ul class="fc-footer-links"><li><a href="<?php echo esc_url( fruitables_home_shop_url() ); ?>"><?php esc_html_e( 'All Products', 'fruitables' ); ?></a></li><?php foreach ( fruitables_home_categories( 5 ) as $term ) : $link = get_term_link( $term ); if ( is_wp_error( $link ) ) { continue; } ?><li><a href="<?php echo esc_url( $link ); ?>"><?php echo esc_html( $term->name ); ?></a></li><?php endforeach; ?></ul></div>
        <div><h2><?php esc_html_e( 'Company', 'fruitables' ); ?></h2><?php if ( has_nav_menu( 'footer_shop' ) ) : wp_nav_menu( array( 'theme_location' => 'footer_shop', 'container' => false, 'menu_class' => 'fc-footer-links', 'depth' => 1, 'fallback_cb' => false ) ); else : ?><ul class="fc-footer-links"><li><a href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php esc_html_e( 'Home', 'fruitables' ); ?></a></li><?php if ( get_privacy_policy_url() ) : ?><li><a href="<?php echo esc_url( get_privacy_policy_url() ); ?>"><?php esc_html_e( 'Privacy Policy', 'fruitables' ); ?></a></li><?php endif; ?></ul><?php endif; ?></div>
        <div><h2><?php esc_html_e( 'Customer Care', 'fruitables' ); ?></h2><?php if ( has_nav_menu( 'footer_account' ) ) : wp_nav_menu( array( 'theme_location' => 'footer_account', 'container' => false, 'menu_class' => 'fc-footer-links', 'depth' => 1, 'fallback_cb' => false ) ); else : ?><ul class="fc-footer-links"><li><a href="#fc-message"><?php esc_html_e( 'Contact Us', 'fruitables' ); ?></a></li><?php if ( function_exists( 'wc_get_page_id' ) && wc_get_page_id( 'myaccount' ) > 0 ) : ?><li><a href="<?php echo esc_url( wc_get_page_permalink( 'myaccount' ) ); ?>"><?php esc_html_e( 'My Account', 'fruitables' ); ?></a></li><?php endif; ?></ul><?php endif; ?></div>
        <div class="fc-footer-newsletter"><h2><?php esc_html_e( 'Subscribe to Our Newsletter', 'fruitables' ); ?></h2><p><?php esc_html_e( 'Get fresh deals, new arrivals and special offers directly in your inbox.', 'fruitables' ); ?></p>
            <?php if ( '' !== trim( $newsletter_html ) ) : ?><div class="fc-newsletter-provider"><?php echo $newsletter_html; // Trusted plugin output. ?></div><?php else : ?><div class="fc-newsletter-preview"><label for="fc-newsletter-email" class="visually-hidden"><?php esc_html_e( 'Email address', 'fruitables' ); ?></label><input id="fc-newsletter-email" type="email" placeholder="<?php esc_attr_e( 'Enter your email address', 'fruitables' ); ?>" disabled><button type="button" disabled aria-label="<?php esc_attr_e( 'Subscribe', 'fruitables' ); ?>"><i class="fas fa-paper-plane" aria-hidden="true"></i></button></div><small><?php esc_html_e( 'Newsletter signup is not available yet.', 'fruitables' ); ?></small><?php endif; ?>
