    <div class="fc-wrap fc-footer-bottom"><span>© <?php echo esc_html( wp_date( 'Y' ) ); ?> <?php echo esc_html( get_bloginfo( 'name' ) ); ?>. <?php esc_html_e( 'All rights reserved.', 'fruitables' ); ?></span><?php if ( get_theme_mod( 'fruitables_footer_payment_show', false ) ) : ?><div class="fc-footer-payment"><span><?php esc_html_e( 'We Accept:', 'fruitables' ); ?></span><img src="<?php echo esc_url( get_theme_file_uri( 'img/payment.png' ) ); ?>" alt="<?php esc_attr_e( 'Accepted payment methods', 'fruitables' ); ?>" width="180" loading="lazy"></div><?php endif; ?></div>
